// Interfejs ma dwie metody (obie domyslnie puste - mozna nadpisac
// tylko te, ktore potrzebujemy):

public class MyContextListener implements ServletContextListener {

    public void contextInitialized(ServletContextEvent sce) {
        // wywolywane RAZ, gdy aplikacja startuje - ZANIM jakikolwiek
        // serwlet obsluzy pierwsze zadanie. Typowe uzycie: inicjalizacja
        // puli polaczen, wczytanie konfiguracji, zaladowanie cache.
        System.out.println("aplikacja startuje");
    }

    public void contextDestroyed(ServletContextEvent sce) {
        // wywolywane RAZ, gdy aplikacja jest zatrzymywana.
        // Typowe uzycie: zwolnienie zasobow z contextInitialized.
        System.out.println("aplikacja sie zatrzymuje");
    }
}

Context context = tomcat.addContext("", null);
Tomcat.addServlet(context, "helloServlet", new HelloServlet());
context.addServletMappingDecoded("/hello", "helloServlet");

// Rejestracja listenera po NAZWIE KLASY - kontener utworzy instancje sam.
context.addApplicationListener(MyContextListener.class.getName());

// KONSEKWENCJA PRAKTYCZNA: klasa listenera MUSI miec dostepny
// publiczny konstruktor bezargumentowy (domyslny, niejawny
// konstruktor tez sie liczy).
